// Voice lobby form validation acceptance (dashboard parity spec, section 7
// slice 1b). Pins the web-side payload rules for the fourteen settings the
// page edits: the eight slash-command settings plus the six import-file-only
// keys. The Builder implements `src/admin/validation-voice-lobby.ts` and
// re-exports it from `src/admin/validation.ts`, following the existing
// validation-*.ts leaves.
//
// Expected RED: this file fails to load — "Failed to resolve import
// ../src/admin/validation-voice-lobby" — until the Builder creates the seam.
// Builder: implement the seam. Do not edit this file.

import { describe, expect, it } from "vitest";
import { ValidationError } from "../src/admin/validation";
import {
  parseVoiceLobbyForm,
  VOICE_LOBBY_FIELDS,
  VOICE_LOBBY_IMPORT_FIELDS,
  VOICE_LOBBY_SLASH_FIELDS,
} from "../src/admin/validation-voice-lobby";

const SLASH_KEYS = [
  "text_channels",
  "position",
  "group",
  "inherit_permissions",
  "default_limit",
  "always_private",
  "access",
  "logging_channel_id",
];

const IMPORT_KEYS = [
  "name_template",
  "time_zone",
  "unique_names",
  "game_aliases",
  "random_names",
  "channel_template",
];

/** A complete browser submission: strings, unchecked boxes absent. */
function validValues(): Record<string, unknown> {
  return {
    text_channels: "private",
    position: "below_lobby",
    group: "123456789012345678",
    inherit_permissions: "on",
    default_limit: "12",
    // always_private unchecked.
    access: "request_to_join",
    logging_channel_id: "123456789012345679",
    name_template: "{game} with {user}",
    time_zone: "Europe/London",
    unique_names: "on",
    game_aliases: "rl = Rocket League\nmc = Minecraft",
    random_names: "The Lobby\nSide Room",
    channel_template: "Lobby {n}",
  };
}

function expectFieldError(values: Record<string, unknown>, field: string): void {
  try {
    parseVoiceLobbyForm(values);
  } catch (err) {
    expect(err).toBeInstanceOf(ValidationError);
    expect((err as ValidationError).fields[field]).toMatch(/.+/);
    return;
  }
  throw new Error(`expected a ${field} error, the payload parsed`);
}

describe("voice lobby field lists", () => {
  it("names exactly the eight slash-command settings", () => {
    expect([...VOICE_LOBBY_SLASH_FIELDS]).toEqual(SLASH_KEYS);
  });

  it("names exactly the six import-file-only keys", () => {
    expect([...VOICE_LOBBY_IMPORT_FIELDS]).toEqual(IMPORT_KEYS);
  });

  it("lists all fourteen editable keys once", () => {
    expect([...VOICE_LOBBY_FIELDS]).toEqual([...SLASH_KEYS, ...IMPORT_KEYS]);
  });
});

describe("voice lobby form parsing", () => {
  it("accepts a complete valid payload with normalized types", () => {
    expect(parseVoiceLobbyForm(validValues())).toEqual({
      text_channels: "private",
      position: "below_lobby",
      group: "123456789012345678",
      inherit_permissions: true,
      default_limit: 12,
      always_private: false,
      access: "request_to_join",
      logging_channel_id: "123456789012345679",
      name_template: "{game} with {user}",
      time_zone: "Europe/London",
      unique_names: true,
      game_aliases: "rl = Rocket League\nmc = Minecraft",
      random_names: "The Lobby\nSide Room",
      channel_template: "Lobby {n}",
    });
  });

  it.each(["inherit_permissions", "always_private", "unique_names"])(
    "reads checkbox %s as on-or-absent",
    (field) => {
      const on = validValues();
      on[field] = "on";
      expect(parseVoiceLobbyForm(on)[field as keyof ReturnType<typeof parseVoiceLobbyForm>]).toBe(
        true,
      );
      const off = validValues();
      delete off[field];
      expect(parseVoiceLobbyForm(off)[field as keyof ReturnType<typeof parseVoiceLobbyForm>]).toBe(
        false,
      );
    },
  );

  it("accepts empty-means-unset for the optional id, template and list keys", () => {
    const values = validValues();
    values["group"] = "";
    values["logging_channel_id"] = "";
    values["channel_template"] = "";
    values["game_aliases"] = "";
    values["random_names"] = "";
    const parsed = parseVoiceLobbyForm(values);
    expect(parsed.group).toBe("");
    expect(parsed.logging_channel_id).toBe("");
    expect(parsed.channel_template).toBe("");
    expect(parsed.game_aliases).toBe("");
    expect(parsed.random_names).toBe("");
  });

  it("ignores unknown keys for forward compatibility", () => {
    const values = validValues();
    values["future_key"] = "future value";
    expect(() => parseVoiceLobbyForm(values)).not.toThrow();
  });

  it("counts characters, not bytes, on text limits", () => {
    const values = validValues();
    values["name_template"] = "é".repeat(100);
    expect(() => parseVoiceLobbyForm(values)).not.toThrow();
    values["name_template"] = "é".repeat(101);
    expectFieldError(values, "name_template");
  });

  it.each([
    // Slash-command settings.
    ["text_channels", "sometimes"],
    ["text_channels", ""],
    ["position", "middle"],
    ["position", ""],
    ["group", "not-an-id"],
    ["group", "123"],
    ["group", "1".repeat(26)],
    ["group", " 123456789012345678 "],
    ["inherit_permissions", "yes"],
    ["default_limit", "abc"],
    ["default_limit", "-1"],
    ["default_limit", "100"],
    ["default_limit", "1.5"],
    ["default_limit", ""],
    ["always_private", "1"],
    ["access", "friends_only"],
    ["access", ""],
    ["logging_channel_id", "chan-1"],
    ["logging_channel_id", "123"],
    // Import-file-only keys.
    ["name_template", ""],
    ["name_template", "   "],
    ["name_template", "x".repeat(101)],
    ["name_template", "bad\0name"],
    ["name_template", "bad\nname"],
    ["time_zone", "Mars/Olympus"],
    ["time_zone", ""],
    ["unique_names", "maybe"],
    ["game_aliases", "a line without an equals sign"],
    ["game_aliases", `${"k".repeat(65)} = v`],
    ["random_names", "x".repeat(51)],
    ["channel_template", "x".repeat(101)],
    ["channel_template", "bad\0template"],
  ] as const)("rejects %s=%s", (field, value) => {
    const values = validValues();
    values[field] = value;
    expectFieldError(values, field);
  });

  it("rejects an alias list past fifty lines", () => {
    const values = validValues();
    values["game_aliases"] = Array.from({ length: 51 }, (_, i) => `a${i} = Game ${i}`).join("\n");
    expectFieldError(values, "game_aliases");
  });

  it("rejects a random-name list past one hundred names", () => {
    const values = validValues();
    values["random_names"] = Array.from({ length: 101 }, (_, i) => `Room ${i}`).join("\n");
    expectFieldError(values, "random_names");
  });

  it("rejects control characters in list values", () => {
    const values = validValues();
    values["random_names"] = "The Lobby\nbad\0room";
    expectFieldError(values, "random_names");
  });

  it("accepts the documented time zones", () => {
    for (const zone of ["Europe/London", "America/New_York", "UTC"]) {
      const values = validValues();
      values["time_zone"] = zone;
      expect(() => parseVoiceLobbyForm(values), zone).not.toThrow();
    }
  });

  it("reports every bad field in one pass", () => {
    const values = validValues();
    values["text_channels"] = "sometimes";
    values["default_limit"] = "abc";
    try {
      parseVoiceLobbyForm(values);
    } catch (err) {
      expect(err).toBeInstanceOf(ValidationError);
      const fields = (err as ValidationError).fields;
      expect(fields["text_channels"]).toMatch(/.+/);
      expect(fields["default_limit"]).toMatch(/.+/);
      return;
    }
    throw new Error("expected both field errors, the payload parsed");
  });
});
